-- Existing EverForge compatibility marker transition ONLY AFTER successful reviewed migration.
-- This is not seed replay, adoption, or a checksum of mutable player data.
-- Set @sod_oceangreen_20261115_marker_authorized=1 after backup/migration acceptance.
DELIMITER $$
CREATE PROCEDURE accept_sod_oceangreen_20261115_seed()
